using System;using System.Linq;using System.Reflection;using TownOfHost;using TownOfHost.Modules;using TownOfHost.Modules.ChatManager;using TownOfHost.Roles.Neutral;using TownOfHost.Roles.Core;
class Program {
static int passed;static PlayerControl host,target,other;static Prankster prank;
static void Check(bool ok,string message){if(!ok)throw new Exception(message);}
static void Reset(){host=new(){PlayerId=0,ClientId=20,NetId=100,Data=new(){NetId=200,PlayerName="Host"}};target=new(){PlayerId=4,ClientId=44,NetId=104,Data=new(){NetId=204,PlayerName="Target"}};other=new(){PlayerId=5,ClientId=45,NetId=105,Data=new(){NetId=205}};PlayerControl.LocalPlayer=host;PlayerCatch.AllPlayerControls=new(){host,target,other};AmongUsClient.Instance.AmHost=true;TownOfHost.Main.MessagesToSend.Clear();TownOfHost.Main.LastNotifyNames.Clear();TownOfHost.Main.AfterMeetingDeathPlayers.Clear();TownOfHost.Main.AllPlayerNames=PlayerCatch.AllPlayerControls.ToDictionary(p=>p.PlayerId,p=>"Player"+p.PlayerId);TownOfHost.Main.MegCount=0;GameStates.IsMeeting=GameStates.CalledMeeting=true;GameStates.IsOutro=GameStates.ExiledAnimate=false;MeetingStates.FirstMeeting=false;MeetingHud.Instance=new();HudManager.Instance.Chat=new();Utils.Restriction=true;Options.ExHideChatCommand.Enabled=false;Options.firstturnmeeting=false;ChatControllerUpdatePatch.IsQuickChatOnly=false;ChatUpdatePatch.DoBlockChat=ChatUpdatePatch.BlockSendName=false;TownOfHost.Roles.Impostor.Assassin.NowUse=false;TownOfHost.Roles.Madmate.MadAvenger.Skill=false;CustomWinnerHolder.WinnerTeam=CustomWinner.Default;CustomRoleManager.AllActiveRoles.Clear();CustomRoleManager.MarkOthers.Clear();MeetingHudPatch.Deaths.Clear();CustomRpcSender.Sent.Clear();Logger.Entries.Clear();SelfVoteManager.Init();Prankster.ResetJack();typeof(Prankster).GetMethod("SetupOptionItem",BindingFlags.Static|BindingFlags.NonPublic).Invoke(null,null);prank=new(host);CustomRoleManager.AllActiveRoles.Add(0,prank);prank.OnStartMeeting();ClearOutput();}
static Prankster.CandyState State=> (Prankster.CandyState)typeof(Prankster).GetField("state",BindingFlags.NonPublic|BindingFlags.Instance).GetValue(prank);
static void ClearOutput(){TownOfHost.Main.MessagesToSend.Clear();CustomRpcSender.Sent.Clear();HudManager.Instance.Chat.Texts.Clear();Logger.Entries.Clear();}
static void Ask(byte id=4){Check(!prank.CheckVoteAsVoter(0,host),"self vote counted");Check(!prank.CheckVoteAsVoter(id,host),"target vote counted");}
static void Dispatch(){while(TownOfHost.Main.MessagesToSend.Count>0)ChatManager.SendMessageInGame(new());}
static void Notice(PlayerControl p,string m="Private notice")=>typeof(Prankster).GetMethod("SendNotice",BindingFlags.NonPublic|BindingFlags.Static).Invoke(null,new object[]{p,m});
static void Test(string n,Action a){Reset();a();passed++;Console.WriteLine("PASS "+n);}
static void Main(string[] args){
Test("request enqueues a standard private notice",()=>{Ask();Check(TownOfHost.Main.MessagesToSend.Count==1&&TownOfHost.Main.MessagesToSend[0].Item2==4,"request bypassed standard private queue");Check(CustomRpcSender.Sent.Count==0,"direct recipient-owned SendChat");});
if(args.Contains("--regression-only")){Console.WriteLine($"RESULT {passed} passed");return;}
Test("self then target creates a pending request once",()=>{Ask();Check(State.Used&&State.Waiting&&State.PendingTarget==4&&State.Requested.SetEquals(new byte[]{4}),"request state");});
Test("official-server Vanilla notice uses host NetId and target ClientId only",()=>{Ask();Dispatch();Check(CustomRpcSender.Sent.Count==1,"packet count");var p=CustomRpcSender.Sent.Single();Check(p.Target==44&&p.Rpcs.All(r=>r.NetId==host.NetId),"wrong source or destination");Check(!p.Rpcs.Any(r=>r.NetId==target.NetId),"recipient-owned RPC");Check(HudManager.Instance.Chat.Texts.All(s=>!s.Contains("お菓子を求められた")),"host received secret prompt");});
Test("full Japanese candy prompt and both commands survive name transport",()=>{Ask();Dispatch();var text=CustomRpcSender.Sent.Single().Rpcs.Where(r=>r.Call==RpcCalls.SetName).First().Values.OfType<string>().Single();Check(text.Contains("/cmd candy 1")&&text.Contains("/cmd candy 2")&&text.Contains("会議終了"),"incomplete Vanilla prompt");});
Test("QuickChat-only route retains prompt in name and uses allowed placeholder",()=>{ChatControllerUpdatePatch.IsQuickChatOnly=true;Ask();Dispatch();var p=CustomRpcSender.Sent.Single();Check(p.Rpcs.Any(r=>r.Call==RpcCalls.SendQuickChat)&&!p.Rpcs.Any(r=>r.Call==RpcCalls.SendChat),"wrong quick-chat route");Check(p.Rpcs.Any(r=>r.Call==RpcCalls.SetName&&r.Values.OfType<string>().Any(s=>s.Contains("/cmd candy 2"))),"prompt lost");});
Test("custom-server hidden-command route remains private",()=>{Utils.Restriction=false;Options.ExHideChatCommand.Enabled=true;Ask();Dispatch();Check(CustomRpcSender.Sent.All(p=>p.Target==44)&&CustomRpcSender.Sent.Count==1,"private route");});
Test("Shell non-host recipient needs no custom notification RPC",()=>{target.Mod=true;Ask();Dispatch();Check(CustomRpcSender.Sent.Single().Rpcs.All(r=>r.Call is RpcCalls.SetName or RpcCalls.SendChat),"custom mod dependency");});
Test("unavailable ClientId cannot enqueue or broadcast",()=>{target.ClientId=-1;Ask();Check(TownOfHost.Main.MessagesToSend.Count==0&&CustomRpcSender.Sent.Count==0,"invalid recipient escaped");Check(Logger.Entries.Any(l=>l.Contains("Private notice skipped")),"missing safe diagnostic");});
Test("disconnect between enqueue and dispatch cannot broadcast",()=>{Ask();target.Data.Disconnected=true;Dispatch();Check(CustomRpcSender.Sent.Count==0,"disconnected recipient escaped");});
Test("missing ClientId at dispatch cannot broadcast",()=>{Ask();target.ClientId=-1;Dispatch();Check(CustomRpcSender.Sent.Count==0,"missing destination became broadcast");});
Test("removed target at dispatch cannot broadcast",()=>{Ask();PlayerCatch.AllPlayerControls.Remove(target);Dispatch();Check(CustomRpcSender.Sent.Count==0,"missing target became broadcast");});
Test("ClientId zero is a valid private address",()=>{target.ClientId=0;Ask();Dispatch();Check(CustomRpcSender.Sent.Single().Target==0,"zero rejected");});
Test("host own notice stays local and restores original name",()=>{Notice(host);Check(HudManager.Instance.Chat.Texts.Count==1&&host.Data.PlayerName=="Host","local display or restoration");Check(CustomRpcSender.Sent.Count==0&&TownOfHost.Main.MessagesToSend.Count==0,"local notice escaped");});
Test("local rendering exception still restores name",()=>{HudManager.Instance.Chat.Throw=true;try{Notice(host);}catch(TargetInvocationException){}Check(host.Data.PlayerName=="Host","name not restored");});
Test("non-host cannot send notices",()=>{AmongUsClient.Instance.AmHost=false;Notice(target);Check(TownOfHost.Main.MessagesToSend.Count==0&&CustomRpcSender.Sent.Count==0,"non-host sent");});
Test("invalid or dummy recipients never enqueue",()=>{Notice(null);target.isDummy=true;Notice(target);target.isDummy=false;target.Data.Disconnected=true;Notice(target);Check(TownOfHost.Main.MessagesToSend.Count==0,"invalid recipients queued");});
Test("give candy command consumes pending request and increments candy",()=>{Ask();ClearOutput();Check(Prankster.TryHandleCandyCommand(target,"/cmd candy 1"),"not handled");Check(State.Candy==1&&!State.Waiting&&State.Curses.Count==0,"give failed");Check(!TownOfHost.Main.MessagesToSend.Any(m=>m.Item2==other.PlayerId),"third-party reply");});
Test("refusal command curses only requested target",()=>{Ask();ClearOutput();Check(Prankster.TryHandleCandyCommand(target,"/cmd candy 2"),"not handled");Check(State.Curses.TryGetValue(4,out var deadline)&&deadline==2&&!State.Waiting,"refusal failed");Check(TownOfHost.Main.MessagesToSend.All(m=>m.Item2==4),"refusal leaked");});
Test("wrong respondent cannot answer another player's request",()=>{Ask();Prankster.TryHandleCandyCommand(other,"/cmd candy 1");Check(State.Waiting&&State.PendingTarget==4&&State.Candy==0,"wrong respondent accepted");});
Test("duplicate answer cannot increment candy twice",()=>{Ask();Prankster.TryHandleCandyCommand(target,"/cmd candy 1");Prankster.TryHandleCandyCommand(target,"/cmd candy 1");Check(State.Candy==1&&!State.Waiting,"double candy");});
Test("invalid answer keeps request pending and sends private usage",()=>{Ask();ClearOutput();Prankster.TryHandleCandyCommand(target,"/cmd candy 3");Check(State.Waiting&&State.Candy==0&&TownOfHost.Main.MessagesToSend.All(m=>m.Item2==4),"invalid command affected request");});
Test("command parser handles prefix and whitespace and ignores ordinary chat",()=>{Check(Prankster.TryParseCandyCommand("/CMD  candy  2",out var n)&&n==2,"parser");Check(!Prankster.TryParseCandyCommand("hello",out _),"ordinary chat consumed");});
Test("no reply becomes one refusal at meeting end",()=>{Ask();ClearOutput();Prankster.MeetingEnded();Check(State.Curses.ContainsKey(4)&&State.Curses[4]==2&&!State.Waiting&&!State.MeetingOpen,"timeout refusal");int count=TownOfHost.Main.MessagesToSend.Count;Prankster.MeetingEnded();Check(TownOfHost.Main.MessagesToSend.Count==count,"double timeout");});
Test("curse survives request meeting and expires after next meeting",()=>{Ask();Prankster.TryHandleCandyCommand(target,"/cmd candy 2");Prankster.MeetingEnded();Check(!MeetingHudPatch.Deaths.Contains(4),"expired too early");prank.OnStartMeeting();Prankster.MeetingEnded();Check(MeetingHudPatch.Deaths.SequenceEqual(new byte[]{4})&&!State.Curses.ContainsKey(4),"expiry failed");});
Test("Prankster death clears curse and pending request",()=>{Ask();Prankster.TryHandleCandyCommand(target,"/cmd candy 2");host.Alive=false;prank.OnDead(host);Check(State.Curses.Count==0&&!State.MeetingOpen&&!State.Waiting,"death cancellation");});
Test("departed target cancels pending request",()=>{Ask();prank.OnLeftPlayer(target);Check(!State.Waiting&&State.PendingTarget==255,"left target pending");});
Test("dead target curse is removed without another kill",()=>{Ask();Prankster.TryHandleCandyCommand(target,"/cmd candy 2");target.Alive=false;prank.OnDead(target);Prankster.MeetingEnded();Check(!State.Curses.ContainsKey(4)&&MeetingHudPatch.Deaths.Count==0,"dead target retained");});
Test("same target cannot be requested again next meeting",()=>{Ask();Prankster.TryHandleCandyCommand(target,"/cmd candy 1");Prankster.MeetingEnded();prank.OnStartMeeting();ClearOutput();Ask();Check(!State.Waiting&&!State.Used&&State.Requested.Count==1,"duplicate target accepted");});
Test("one request per meeting is enforced",()=>{Ask();prank.CheckVoteAsVoter(5,host);Check(State.PendingTarget==4&&State.Requested.Count==1,"second request accepted");});
Test("Jack request reveals Prankster without candy waiting or curse",()=>{typeof(Prankster).GetField("jackId",BindingFlags.Static|BindingFlags.NonPublic).SetValue(null,(byte)4);Ask();Check(State.Revealed&&!State.Waiting&&State.Curses.Count==0,"Jack behavior");});
Test("Jack disclosure explicitly addresses each participant without broadcast",()=>{typeof(Prankster).GetField("jackId",BindingFlags.Static|BindingFlags.NonPublic).SetValue(null,(byte)4);Ask();Dispatch();Check(CustomRpcSender.Sent.Select(p=>p.Target).OrderBy(i=>i).SequenceEqual(new[]{44,45}),"Jack disclosure destinations");Check(CustomRpcSender.Sent.All(p=>p.Target>=0),"Jack broadcast");});
Test("unanswered departed target is not cursed at meeting end",()=>{Ask();target.Data.Disconnected=true;Prankster.MeetingEnded();Check(State.Curses.Count==0&&!State.Waiting,"departed target cursed");});
Test("safe diagnostics never contain prompt or player name",()=>{Ask();Check(Logger.Entries.Any(l=>l.Contains("Private notice queued: recipient=4")),"missing queue diagnostic");Check(Logger.Entries.All(l=>!l.Contains("/cmd candy")&&!l.Contains("お菓子")&&!l.Contains("Target")),"prompt logged");});
Test("dead host notice uses private alive snapshot then restores dead state",()=>{host.Alive=false;host.Data.IsDead=true;Notice(target);Dispatch();var p=CustomRpcSender.Sent.Single();Check(p.Target==44&&p.Snapshots.SequenceEqual(new object[]{false,true}),"dead-host visibility snapshots");Check(host.Data.IsDead&&!host.Alive,"host state changed");Check(p.Rpcs.Last().Call==RpcCalls.SetName&&p.Rpcs.Last().NetId==host.NetId,"dead host name restoration targeted PlayerData instead of PlayerControl");});
Test("four successive games with 15 players clear request and curse state",()=>{for(int game=1;game<=4;game++){Reset();foreach(byte id in Enumerable.Range(0,15).Select(i=>(byte)i)){if(PlayerCatch.GetPlayerById(id)!=null)continue;var pc=new PlayerControl{PlayerId=id,ClientId=40+id,NetId=(uint)(100+id)};PlayerCatch.AllPlayerControls.Add(pc);TownOfHost.Main.AllPlayerNames[id]="Player"+id;}Ask();Dispatch();Check(PlayerCatch.AllPlayerControls.Count==15&&CustomRpcSender.Sent.Count==1&&CustomRpcSender.Sent.Single().Target==44,"15-player private request");Check(State.Candy==0&&State.Meeting==1&&State.Curses.Count==0,"state leaked across games");Prankster.TryHandleCandyCommand(target,"/cmd candy 2");Prankster.MeetingEnded();prank.OnDestroy();}});
Console.WriteLine($"RESULT {passed} passed, 0 failed");
}
}
